// Draws a Gnome Theft Auto region's things as the game places them: its props through the prefab library, each marker as a thin
// post coloured by kind, and the markers that cover a footprint (areas, reserved zones, Fort Sandpit, still-water bodies) as
// translucent boxes. The region's roads and water courses are not drawn here: the ground colour shows them. The scattered trees, cacti and farms are generated by
// the game at run time and are not in the document, so they are not drawn either.
import * as THREE from 'three';
import { buildPrefab, getPrefab } from '@lawn/prefabs';
import type { EditorContext } from '../context';
import type { GtaLevel } from './gtaLevel';

const MAGENTA = 0xff00ff;
const POST_COLOUR: Record<string, number> = {
  spawn: 0x4ad6ff, landmark: 0xffffff, area: 0x7fd17a, portal: 0xc27bff, giver: 0xffb347,
  site: 0xc27bff, setpiece: 0x7fd17a, reserve: 0xff8a8a, walk: 0xa0ffd0, water: 0x3d8fd6,
};

const mat = (color: number, extra: Partial<THREE.MeshLambertMaterialParameters> = {}): THREE.MeshLambertMaterial =>
  new THREE.MeshLambertMaterial({ color, flatShading: true, ...extra });

const finite = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

export function createGtaObjectView(ctx: EditorContext): { dispose(): void } {
  const scene = ctx.viewport.scene;
  const root = new THREE.Group();
  root.name = 'object-view';
  const structures = new THREE.Group();
  const flora = new THREE.Group(); // none at run time: the scattered scenery is the game's own; the View tool's layer toggles expect the second group
  root.add(structures, flora);
  scene.add(root);

  function clear(): void {
    for (const c of [...structures.children]) {
      structures.remove(c);
      c.traverse((o) => {
        if (o instanceof THREE.Mesh && !o.userData.shared) {
          o.geometry.dispose();
          (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => m.dispose());
        }
      });
    }
  }

  function box(w: number, h: number, d: number, color: number, x: number, y: number, z: number, extra: Partial<THREE.MeshLambertMaterialParameters> = {}): void {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color, extra));
    m.position.set(x, y, z);
    structures.add(m);
  }

  /** A see-through box standing on the ground, centred on (x, z). */
  const zone = (w: number, d: number, color: number, x: number, z: number): void =>
    box(w, 1, d, color, x, 0.5, z, { transparent: true, opacity: 0.25, depthWrite: false });

  function build(): void {
    clear();
    const level = ctx.zones[ctx.zone] as unknown as GtaLevel;
    for (const p of level.props) {
      if (!getPrefab(p.prefab)) {
        box(0.8, 0.8, 0.8, MAGENTA, p.x, 0.4, p.z); // an unknown prefab id stays visible and pickable
        continue;
      }
      const tint = p.tint && /^#[0-9a-f]{6}$/i.test(p.tint) ? parseInt(p.tint.slice(1), 16) : undefined;
      const g = buildPrefab(p.prefab, { scale: p.scale ?? 1, ...(tint !== undefined ? { tint } : {}) });
      g.position.set(p.x, 0, p.z);
      g.rotation.y = p.rot ?? 0;
      g.traverse((o) => { o.userData.shared = true; });
      structures.add(g);
    }
    for (const m of level.markers) {
      const colour = POST_COLOUR[m.kind] ?? 0xffffff;
      box(0.15, 3, 0.15, colour, m.x, 1.5, m.z);
      const d = (m.data ?? {}) as Record<string, unknown>;
      if (m.kind === 'area' || m.kind === 'water') zone(finite(d.w), finite(d.d), colour, m.x, m.z);
      if (m.kind === 'reserve') zone(2 * finite(d.hw), 2 * finite(d.hd), colour, m.x, m.z);
      if (m.kind === 'site' && m.id === 'fort-sandpit') zone(finite(d.w), finite(d.d), colour, m.x, m.z);
    }
  }

  build();
  let pending = false;
  let alive = true;
  const rebuild = (): void => {
    if (pending) return;
    pending = true;
    requestAnimationFrame(() => { pending = false; if (alive) build(); });
  };
  const off = ctx.events.changed.on(rebuild);
  const offZone = ctx.events.zone.on(rebuild);
  return { dispose() { alive = false; off(); offZone(); clear(); scene.remove(root); } };
}
